import { jsonResponse, errorResponse } from '../../utils/responses.js';
import { requireFiel } from '../../middleware/auth.js';
import { sendTermoConfirmationEmail, sendTermoNotificationToSecretariat } from '../../utils/emails.js';

export async function getDados(request, env) {
  const auth = await requireFiel(request, env);
  if (auth instanceof Response) return auth;
  const url = new URL(request.url);
  const email = url.searchParams.get('email') || auth.email;
  if (!email) return errorResponse('E-mail é obrigatório', 400);
  try {
    const db = env.DB;
    const stmt = db.prepare(`SELECT musicas, versiculos, oracoes, fotos, termo_aceito, termo_data FROM fiel_dados WHERE email = ?`);
    const result = await stmt.bind(email).first();
    if (!result) {
      await db.prepare(`INSERT INTO fiel_dados (email, musicas, versiculos, oracoes, fotos, termo_aceito, created_at, updated_at) VALUES (?, '[]', '[]', '[]', '[]', 0, ?, ?)`).bind(email, new Date().toISOString(), new Date().toISOString()).run();
      return jsonResponse({ success: true, musicas: [], versiculos: [], oracoes: [], fotos: [], termoAceito: false, termoData: null });
    }
    return jsonResponse({
      success: true,
      musicas: JSON.parse(result.musicas || '[]'),
      versiculos: JSON.parse(result.versiculos || '[]'),
      oracoes: JSON.parse(result.oracoes || '[]'),
      fotos: JSON.parse(result.fotos || '[]'),
      termoAceito: result.termo_aceito === 1,
      termoData: result.termo_data ? JSON.parse(result.termo_data) : null
    });
  } catch (error) {
    console.error('Erro ao carregar dados:', error);
    return errorResponse('Erro ao carregar dados', 500);
  }
}

export async function salvarDados(request, env) {
  try {
    const body = await request.json();
    const { email, musicas, versiculos, oracoes, fotos } = body;
    if (!email) return errorResponse('E-mail é obrigatório', 400);
    const db = env.DB;
    const now = new Date().toISOString();
    const existing = await db.prepare('SELECT email FROM fiel_dados WHERE email = ?').bind(email).first();
    if (existing) {
      await db.prepare(`UPDATE fiel_dados SET musicas = ?, versiculos = ?, oracoes = ?, fotos = ?, updated_at = ? WHERE email = ?`).bind(JSON.stringify(musicas ?? []), JSON.stringify(versiculos ?? []), JSON.stringify(oracoes ?? []), JSON.stringify(fotos ?? []), now, email).run();
    } else {
      await db.prepare(`INSERT INTO fiel_dados (email, musicas, versiculos, oracoes, fotos, termo_aceito, created_at, updated_at) VALUES (?, ?, ?, ?, ?, 0, ?, ?)`).bind(email, JSON.stringify(musicas ?? []), JSON.stringify(versiculos ?? []), JSON.stringify(oracoes ?? []), JSON.stringify(fotos ?? []), now, now).run();
    }
    return jsonResponse({ success: true, message: 'Dados salvos com sucesso' });
  } catch (error) {
    console.error('Erro ao salvar dados:', error);
    return errorResponse('Erro ao salvar dados', 500);
  }
}

export async function atualizarPerfil(request, env) {
  try {
    const body = await request.json();
    const { email, nome, telefone, avatar } = body;
    if (!email) return errorResponse('E-mail é obrigatório', 400);
    const db = env.DB;
    const now = new Date().toISOString();
    const existing = await db.prepare('SELECT email FROM fiel_dados WHERE email = ?').bind(email).first();
    if (existing) {
      await db.prepare(`UPDATE fiel_dados SET nome = ?, telefone = ?, avatar = ?, updated_at = ? WHERE email = ?`).bind(nome ?? null, telefone ?? null, avatar ?? null, now, email).run();
    } else {
      await db.prepare(`INSERT INTO fiel_dados (email, nome, telefone, avatar, musicas, versiculos, oracoes, fotos, termo_aceito, created_at, updated_at) VALUES (?, ?, ?, ?, '[]', '[]', '[]', '[]', 0, ?, ?)`).bind(email, nome ?? null, telefone ?? null, avatar ?? null, now, now).run();
    }
    return jsonResponse({ success: true, message: 'Perfil atualizado com sucesso' });
  } catch (error) {
    console.error('Erro ao atualizar perfil:', error);
    return errorResponse('Erro ao atualizar perfil', 500);
  }
}

export async function listarPastorais(request, env) {
  try {
    const db = env.DB;
    const { results } = await db.prepare(`SELECT id, nome, descricao, responsavel, contato, ativo FROM pastorais WHERE ativo = 1 ORDER BY nome ASC`).all();
    return jsonResponse({ success: true, pastorais: results ?? [] });
  } catch (error) {
    console.error('Erro ao listar pastorais:', error);
    return jsonResponse({ success: true, pastorais: [] });
  }
}

export async function registrarTermo(request, env, ctx) {
  const auth = await requireFiel(request, env);
  if (auth instanceof Response) return auth;
  try {
    const body = await request.json();
    const { email, aceito, dados } = body;
    const emailFinal = email || auth.email;
    const nomeFinal = auth.nome || auth.name || emailFinal;
    if (!emailFinal) return errorResponse('E-mail é obrigatório', 400);
    if (aceito === undefined || aceito === null) return errorResponse('Campo "aceito" é obrigatório', 400);
    const db = env.DB;
    const now = new Date().toISOString();
    const ip = request.headers.get('CF-Connecting-IP') ?? null;
    const termoData = JSON.stringify({ aceito: !!aceito, data: now, ip, userAgent: request.headers.get('User-Agent')?.substring(0, 200) ?? null, dadosExtras: dados ?? null });
    const existing = await db.prepare('SELECT email FROM fiel_dados WHERE email = ?').bind(emailFinal).first();
    if (existing) {
      await db.prepare(`UPDATE fiel_dados SET termo_aceito = ?, termo_data = ?, updated_at = ? WHERE email = ?`).bind(aceito ? 1 : 0, termoData, now, emailFinal).run();
    } else {
      await db.prepare(`INSERT INTO fiel_dados (email, musicas, versiculos, oracoes, fotos, termo_aceito, termo_data, created_at, updated_at) VALUES (?, '[]', '[]', '[]', '[]', ?, ?, ?, ?)`).bind(emailFinal, aceito ? 1 : 0, termoData, now, now).run();
    }
    if (ctx) {
      ctx.waitUntil(sendTermoConfirmationEmail(env, { nome: nomeFinal, email: emailFinal, aceito: !!aceito }));
      ctx.waitUntil(sendTermoNotificationToSecretariat(env, { nome: nomeFinal, email: emailFinal, aceito: !!aceito, ip }));
    }
    return jsonResponse({ success: true, message: aceito ? 'Termo aceito e registrado com sucesso!' : 'Termo recusado registrado.', termoAceito: !!aceito, data: now });
  } catch (error) {
    console.error('Erro ao registrar termo:', error);
    return errorResponse('Erro ao registrar termo: ' + error.message, 500);
  }
}