// src/utils/sanitize.js

/**
 * Sanitiza entrada de dados para prevenir XSS e injeção
 */
export function sanitizeInput(input) {
  if (input === null || input === undefined) {
    return null;
  }
  
  if (typeof input === 'string') {
    return input
      .trim()
      .replace(/[<>]/g, '')
      .replace(/&/g, '&amp;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;')
      .replace(/\//g, '&#x2F;')
      .slice(0, 5000);
  }
  
  if (typeof input === 'object' && !Array.isArray(input)) {
    const sanitized = {};
    for (const [key, value] of Object.entries(input)) {
      const safeKey = typeof key === 'string' ? key.slice(0, 100) : key;
      sanitized[safeKey] = sanitizeInput(value);
    }
    return sanitized;
  }
  
  if (Array.isArray(input)) {
    return input.slice(0, 100).map(item => sanitizeInput(item));
  }
  
  if (typeof input === 'number') {
    return Math.min(Math.max(input, -999999999), 999999999);
  }
  
  return input;
}

/**
 * Gera hash SHA-256 de um token
 */
export async function hashToken(token) {
  const encoder = new TextEncoder();
  const data = encoder.encode(token);
  const hash = await crypto.subtle.digest('SHA-256', data);
  
  return Array.from(new Uint8Array(hash))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('');
}

/**
 * Valida tamanho do payload
 */
export function validatePayloadSize(request, maxSize = 1048576) {
  const contentLength = request.headers.get('content-length');
  
  if (contentLength && parseInt(contentLength) > maxSize) {
    return new Response(
      JSON.stringify({ success: false, error: 'Payload muito grande' }),
      { status: 413, headers: { 'Content-Type': 'application/json' } }
    );
  }

  return null;
}

/**
 * Fetch com timeout
 */
export async function fetchWithTimeout(url, options = {}, timeout = 5000) {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeout);
  
  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    clearTimeout(timeoutId);
    return response;
  } catch (error) {
    clearTimeout(timeoutId);
    if (error.name === 'AbortError') {
      throw new Error('Request timeout');
    }
    throw error;
  }
}

/**
 * Gera ID único da requisição
 */
export function createRequestId() {
  return crypto.randomUUID();
}