// ============================================
// 🔥 FIREWALL / WAF SIMPLES (COMPATÍVEL)
// ============================================

export async function firewall(context) {
  try {
    const { request } = context;

    if (!request) {
      console.error('🔥 Firewall: request undefined');
      return null;
    }

    const ua = request.headers.get('User-Agent') || '';
    const ip =
      request.headers.get('CF-Connecting-IP') ||
      request.headers.get('X-Forwarded-For') ||
      'unknown';

    // 🚫 bloqueia user-agent vazio ou muito curto
    if (!ua || ua.length < 10) {
      return new Response(
        JSON.stringify({ success: false, error: 'User-Agent inválido' }),
        { status: 403, headers: { 'Content-Type': 'application/json' } }
      );
    }

    const blockedAgents = [
      'curl',
      'wget',
      'python',
      'bot',
      'spider',
      'crawler',
      'scrapy'
    ];

    const uaLower = ua.toLowerCase();

    if (blockedAgents.some(b => uaLower.includes(b))) {
      return new Response(
        JSON.stringify({ success: false, error: 'Bot detectado' }),
        { status: 403, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // 🚫 IP suspeito
    if (ip === '0.0.0.0' || ip === '127.0.0.1') {
      return new Response(
        JSON.stringify({ success: false, error: 'IP inválido' }),
        { status: 403, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // ✅ liberado
    return null;

  } catch (err) {
    console.error('🔥 firewall error:', err);

    // ⚠️ em erro interno → NÃO bloquear usuário
    return null;
  }
}