// backend/worker/src/utils/cors.js

// Configuração CORS
export const corsHeaders = {
  'Access-Control-Allow-Origin': '*', // Em produção, substitua pelo seu domínio
  'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
  'Access-Control-Max-Age': '86400',
};

// Handler para requisições OPTIONS (preflight)
export function handleCorsOptions(request) {
  if (request.method === 'OPTIONS') {
    return new Response(null, {
      status: 204,
      headers: corsHeaders,
    });
  }
  return null;
}

// Função para adicionar headers CORS a uma resposta existente
export function addCorsHeaders(response) {
  // Se já for uma Response, cria uma nova com os headers
  const newResponse = new Response(response.body, response);
  
  // Adiciona todos os headers CORS
  Object.entries(corsHeaders).forEach(([key, value]) => {
    newResponse.headers.set(key, value);
  });
  
  return newResponse;
}

// Função para criar uma resposta de erro com CORS
export function corsErrorResponse(message, status = 500) {
  return new Response(
    JSON.stringify({ 
      success: false, 
      error: message 
    }), {
      status: status,
      headers: {
        'Content-Type': 'application/json',
        ...corsHeaders,
      }
    }
  );
}

// Função para criar uma resposta de sucesso com CORS
export function corsSuccessResponse(data, status = 200) {
  return new Response(
    JSON.stringify({ 
      success: true, 
      ...data 
    }), {
      status: status,
      headers: {
        'Content-Type': 'application/json',
        ...corsHeaders,
      }
    }
  );
}