import { jsonResponse } from '../../utils/helpers.js';

// Configure sua chave de API do YouTube
// Coloque no ambiente do Worker: YOUTUBE_API_KEY
const YOUTUBE_API_KEY = 'AIzaSyDAjMrZU6p-LUW_DxV9-LiY5-PQXtM5euY';

/**
 * Busca músicas no YouTube
 * GET /api/fiel/buscar-musicas?q=nome+da+musica
 */
export async function buscarMusicas(request, env) {
  const url = new URL(request.url);
  const query = url.searchParams.get('q');
  
  if (!query || query.trim() === '') {
    return jsonResponse({ success: false, error: 'Digite o nome da música ou artista' }, 400);
  }
  
  try {
    // Usar a chave do ambiente ou a padrão
    const apiKey = env.YOUTUBE_API_KEY || YOUTUBE_API_KEY;
    
    // Buscar no YouTube Data API v3 - Músicas (categoria 10)
    const searchResponse = await fetch(
      `https://www.googleapis.com/youtube/v3/search?part=snippet&maxResults=12&q=${encodeURIComponent(query)}&type=video&videoCategoryId=10&key=${apiKey}`
    );
    
    const searchData = await searchResponse.json();
    
    // Verificar erro da API
    if (searchData.error) {
      console.error('Erro na API do YouTube:', searchData.error);
      return jsonResponse({ success: false, error: searchData.error.message || 'Erro na API do YouTube' }, 500);
    }
    
    if (!searchData.items || searchData.items.length === 0) {
      return jsonResponse({ success: false, error: 'Nenhuma música encontrada' }, 404);
    }
    
    // Buscar detalhes dos vídeos (thumbnail maior, duração)
    const videoIds = searchData.items.map(item => item.id.videoId).join(',');
    const detailsResponse = await fetch(
      `https://www.googleapis.com/youtube/v3/videos?part=contentDetails,snippet&id=${videoIds}&key=${apiKey}`
    );
    const detailsData = await detailsResponse.json();
    
    const tracks = searchData.items.map((item) => {
      const detail = detailsData.items?.find(v => v.id === item.id.videoId);
      const duration = detail?.contentDetails?.duration || '';
      
      // Converter duração ISO 8601 para mm:ss
      let durationFormatted = '';
      if (duration) {
        const match = duration.match(/PT(\d+H)?(\d+M)?(\d+S)?/);
        const hours = (match?.[1] || '').replace('H', '');
        const minutes = (match?.[2] || '').replace('M', '');
        const seconds = (match?.[3] || '').replace('S', '');
        if (hours) {
          durationFormatted = `${hours}:${minutes.padStart(2, '0')}:${seconds.padStart(2, '0')}`;
        } else {
          durationFormatted = `${minutes.padStart(2, '0')}:${seconds.padStart(2, '0')}`;
        }
      }
      
      return {
        id: item.id.videoId,
        nome: item.snippet.title,
        artista: item.snippet.channelTitle,
        imagemUrl: item.snippet.thumbnails.high?.url || item.snippet.thumbnails.medium?.url,
        youtubeUrl: `https://www.youtube.com/watch?v=${item.id.videoId}`,
        previewUrl: `https://www.youtube.com/watch?v=${item.id.videoId}`,
        duracao: durationFormatted
      };
    });
    
    return jsonResponse({ success: true, tracks });
    
  } catch (error) {
    console.error('Erro ao buscar músicas no YouTube:', error);
    return jsonResponse({ success: false, error: 'Erro ao buscar músicas' }, 500);
  }
}

/**
 * Busca uma música específica por ID
 * GET /api/fiel/musica?id=VIDEO_ID
 */
export async function getMusicaById(request, env) {
  const url = new URL(request.url);
  const videoId = url.searchParams.get('id');
  
  if (!videoId) {
    return jsonResponse({ success: false, error: 'ID do vídeo é obrigatório' }, 400);
  }
  
  try {
    const apiKey = env.YOUTUBE_API_KEY || YOUTUBE_API_KEY;
    
    const response = await fetch(
      `https://www.googleapis.com/youtube/v3/videos?part=snippet,contentDetails&id=${videoId}&key=${apiKey}`
    );
    const data = await response.json();
    
    if (data.error) {
      console.error('Erro na API do YouTube:', data.error);
      return jsonResponse({ success: false, error: data.error.message || 'Erro na API do YouTube' }, 500);
    }
    
    if (!data.items || data.items.length === 0) {
      return jsonResponse({ success: false, error: 'Música não encontrada' }, 404);
    }
    
    const item = data.items[0];
    const duration = item.contentDetails.duration || '';
    
    let durationFormatted = '';
    if (duration) {
      const match = duration.match(/PT(\d+H)?(\d+M)?(\d+S)?/);
      const hours = (match?.[1] || '').replace('H', '');
      const minutes = (match?.[2] || '').replace('M', '');
      const seconds = (match?.[3] || '').replace('S', '');
      if (hours) {
        durationFormatted = `${hours}:${minutes.padStart(2, '0')}:${seconds.padStart(2, '0')}`;
      } else {
        durationFormatted = `${minutes.padStart(2, '0')}:${seconds.padStart(2, '0')}`;
      }
    }
    
    const track = {
      id: item.id,
      nome: item.snippet.title,
      artista: item.snippet.channelTitle,
      imagemUrl: item.snippet.thumbnails.high?.url || item.snippet.thumbnails.medium?.url,
      youtubeUrl: `https://www.youtube.com/watch?v=${item.id}`,
      previewUrl: `https://www.youtube.com/watch?v=${item.id}`,
      duracao: durationFormatted
    };
    
    return jsonResponse({ success: true, track });
    
  } catch (error) {
    console.error('Erro ao buscar música:', error);
    return jsonResponse({ success: false, error: 'Erro ao buscar música' }, 500);
  }
}

/**
 * Obtém player para a música (embed URL)
 * GET /api/fiel/musica/player?id=VIDEO_ID
 */
export async function getMusicaPlayer(request, env) {
  const url = new URL(request.url);
  const videoId = url.searchParams.get('id');
  
  if (!videoId) {
    return jsonResponse({ success: false, error: 'ID do vídeo é obrigatório' }, 400);
  }
  
  // Retorna o embed URL para o player
  const embedUrl = `https://www.youtube.com/embed/${videoId}?autoplay=1&controls=1&rel=0`;
  
  return jsonResponse({
    success: true,
    embedUrl,
    videoId
  });
}