import { jsonResponse } from '../../utils/helpers.js';
import { rateLimit } from '../../middleware/rate-limit.js';
import { firewall } from '../../middleware/firewall.js';
import { sha256 } from '../../security/hash.js';
import { hashToken } from '../../utils/sanitize.js';
import { validateTOTP } from '../../utils/totp.js';

// ============================================
// 🔥 FUNÇÃO DE CRIAÇÃO DE SESSÃO (COMPARTILHADA)
// ============================================

/**
 * Cria uma sessão segura para o usuário
 * @param {Object} env - Environment variables
 * @param {Object} user - Dados do usuário
 * @returns {Promise<{token: string, expiresAt: number}>}
 */
export async function createSession(env, user) {
  // Gera token seguro
  const rawToken = crypto.randomUUID();
  const tokenHash = await hashToken(rawToken);
  const expiresAt = Date.now() + (1000 * 60 * 60 * 24 * 7); // 7 dias

  // Salva hash do token no banco
  await env.DB.prepare(`
    UPDATE users 
    SET token_hash = ?, token_expires = ?
    WHERE id = ?
  `).bind(tokenHash, expiresAt, user.id).run();

  // Salva sessão no KV
  await env.KV_SESSION.put(`sess:${tokenHash}`, JSON.stringify({
    user: {
      id: user.id,
      nome: user.nome,
      email: user.email,
      role: user.role
    },
    expires: expiresAt
  }), {
    expirationTtl: 60 * 60 * 24 * 7 // 7 dias
  });

  return { token: rawToken, expiresAt };
}

// ============================================
// UTILITÁRIOS
// ============================================

/**
 * Verifica senha - suporta texto puro e SHA-256
 */
async function verificarSenha(senhaDigitada, senhaArmazenada) {
  if (!senhaArmazenada) return false;
  if (senhaDigitada === senhaArmazenada) return true;
  const hash = await sha256(senhaDigitada);
  return hash === senhaArmazenada;
}

function generatePIN() {
  return Math.floor(100000 + Math.random() * 900000).toString();
}

function generateBackupCodes() {
  return Array.from({ length: 8 }, () =>
    crypto.randomUUID().replace(/-/g, '').slice(0, 8).toUpperCase()
  );
}

// 🔥 GERADOR DE SECRET BASE32 PARA 2FA
function generateBase32Secret(length = 16) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let result = '';
  for (let i = 0; i < length; i++) {
    result += chars[Math.floor(Math.random() * chars.length)];
  }
  return result;
}

async function sendEmail(env, to, subject, html) {
  if (!env.RESEND_API_KEY) { console.warn('⚠️ RESEND_API_KEY não configurada'); return; }
  try {
    await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${env.RESEND_API_KEY}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        from: 'Santuário de Fátima <noreply@mail.santuariodefatima.com.br>',
        to: [to], subject, html
      })
    });
  } catch (e) { console.error('Erro ao enviar e-mail:', e); }
}

async function ensureColumns(env) {
  const extras = [
    'login_pin TEXT',
    'login_pin_expires INTEGER',
    'token TEXT',
    'token_hash TEXT',
    'token_expires INTEGER',
    'backup_codes TEXT',
    'twofa_secret TEXT',
    'twofa_enabled INTEGER DEFAULT 0',
    'celular TEXT',
    'last_login_at TEXT',
    'failed_attempts INTEGER DEFAULT 0',
    'locked_until INTEGER DEFAULT 0'
  ];
  for (const col of extras) {
    try { await env.DB.prepare(`ALTER TABLE users ADD COLUMN ${col}`).run(); } catch (_) {}
  }
}

function validarEmail(email) {
  return email && email.includes('@') && email.length <= 255;
}

function validarCelular(celular) {
  const digits = celular?.replace(/\D/g, '') || '';
  return digits.length >= 10 && digits.length <= 11;
}

function validarSenha(senha) {
  const checks = {
    length: senha.length >= 8,
    uppercase: /[A-Z]/.test(senha),
    lowercase: /[a-z]/.test(senha),
    number: /[0-9]/.test(senha),
    special: /[!@#$%^&*(),.?":{}|<>]/.test(senha)
  };
  const score = Object.values(checks).filter(Boolean).length;
  return { isValid: score >= 4, checks, score };
}

// ============================================
// 1. LOGIN (COM FIREWALL + RATE LIMIT + CREATE SESSION)
// ============================================
export async function fielLoginRoute(request, env) {
  await ensureColumns(env);
  
  // 🔒 FIREWALL
  if (!firewall(request)) {
    return new Response("Blocked", { status: 403 });
  }

  // 🔒 RATE LIMIT
  const allowed = await rateLimit(request, env);
  if (!allowed) {
    return new Response("Too many requests", { status: 429 });
  }

  try {
    const body = await request.json();
    const { email, senha } = body;

    console.log('🔐 Login unificado - email:', email);

    if (!email || !senha) {
      return jsonResponse({ success: false, error: 'Preencha todos os campos' });
    }

    const emailNorm = email.toLowerCase().trim();

    const user = await env.DB.prepare(
      `SELECT id, nome, email, senha_hash, role, twofa_enabled, twofa_secret,
              backup_codes, celular, failed_attempts, locked_until
       FROM users WHERE LOWER(email) = ?`
    ).bind(emailNorm).first();

    if (!user) {
      return jsonResponse({ success: false, error: 'E-mail ou senha inválidos' });
    }

    if (user.locked_until && user.locked_until > Date.now()) {
      const waitMinutes = Math.ceil((user.locked_until - Date.now()) / 60000);
      return jsonResponse({ success: false, error: `Conta bloqueada. Tente novamente em ${waitMinutes} minutos.` });
    }

    const senhaOk = await verificarSenha(senha, user.senha_hash);
    if (!senhaOk) {
      const newAttempts = (user.failed_attempts || 0) + 1;
      let lockUntil = 0;
      if (newAttempts >= 5) {
        lockUntil = Date.now() + 15 * 60 * 1000;
      }
      await env.DB.prepare(
        `UPDATE users SET failed_attempts = ?, locked_until = ? WHERE id = ?`
      ).bind(newAttempts, lockUntil, user.id).run();
      return jsonResponse({ success: false, error: 'E-mail ou senha inválidos' });
    }

    await env.DB.prepare(
      `UPDATE users SET failed_attempts = 0, locked_until = 0 WHERE id = ?`
    ).bind(user.id).run();

    const pin = generatePIN();
    const pinExpiry = Date.now() + 10 * 60 * 1000;

    await env.DB.prepare(
      `UPDATE users SET login_pin = ?, login_pin_expires = ?, last_login_at = ? WHERE id = ?`
    ).bind(pin, pinExpiry, new Date().toISOString(), user.id).run();

    const nome = user.nome || 'Usuário';
    await sendEmail(env, user.email, 'Seu código de acesso - Santuário de Fátima', `
      <div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;">
        <div style="background:#0d2a5c;padding:20px;text-align:center;">
          <h2 style="color:white;margin:0;">🔐 Código de Acesso</h2>
        </div>
        <div style="padding:24px;">
          <p>Olá <strong>${nome}</strong>,</p>
          <p>Seu código de verificação é: <strong style="font-size:24px">${pin}</strong></p>
          <p>Válido por <strong>10 minutos</strong>.</p>
        </div>
      </div>
    `);

    return jsonResponse({
      success: true,
      nextStep: 'pin',
      userId: user.id,
      email: user.email,
      nome,
      role: user.role,
      isAdmin: user.role === 'admin',
      has2FA: user.twofa_enabled === 1 || !!user.twofa_secret
    });

  } catch (err) {
    console.error('❌ fielLoginRoute:', err);
    return jsonResponse({ success: false, error: 'Erro interno: ' + err.message }, 500);
  }
}

// ============================================
// 2. REGISTRO
// ============================================
export async function fielRegisterRoute(request, env) {
  try {
    const body = await request.json();
    const { nome, email, senha, celular } = body;

    if (!nome || !email || !senha) {
      return jsonResponse({ success: false, error: 'Preencha todos os campos obrigatórios' });
    }
    if (!validarEmail(email)) {
      return jsonResponse({ success: false, error: 'E-mail inválido' });
    }
    if (!validarCelular(celular)) {
      return jsonResponse({ success: false, error: 'Celular inválido (com DDD, mínimo 10 dígitos)' });
    }

    const senhaValidation = validarSenha(senha);
    if (!senhaValidation.isValid) {
      return jsonResponse({ success: false, error: 'Senha fraca. Use maiúsculas, minúsculas, números e caracteres especiais.' });
    }

    const emailNorm = email.toLowerCase().trim();
    await ensureColumns(env);

    const existe = await env.DB.prepare(
      "SELECT id FROM users WHERE LOWER(email) = ?"
    ).bind(emailNorm).first();
    
    if (existe) {
      return jsonResponse({ success: false, error: 'E-mail já cadastrado' });
    }

    const senha_hash = await sha256(senha);
    const id = crypto.randomUUID();

    await env.DB.prepare(`
      INSERT INTO users (id, nome, email, senha_hash, celular, role, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?, 'fiel', ?, ?)
    `).bind(
      id, nome.trim(), emailNorm, senha_hash, celular.replace(/\D/g, ''),
      new Date().toISOString(), new Date().toISOString()
    ).run();

    return jsonResponse({ success: true, message: 'Cadastro realizado com sucesso!' });

  } catch (err) {
    console.error('❌ fielRegisterRoute:', err);
    return jsonResponse({ success: false, error: 'Erro interno: ' + err.message }, 500);
  }
}

// ============================================
// 3. VERIFICAR TOKEN (COM KV)
// ============================================
export async function fielVerificarRoute(request, env) {
  try {
    const authHeader = request.headers.get('Authorization');
    const token = authHeader?.replace('Bearer ', '');

    console.log('🔍 Verificando token:', token ? 'Token presente' : 'Token ausente');

    if (!token) {
      return jsonResponse({ success: false, error: 'Token não fornecido' }, 401);
    }

    // 🔥 BUSCA SESSÃO NO KV
    const hash = await sha256(token);
    const sessionData = await env.KV_SESSION.get(`sess:${hash}`, 'json');

    if (!sessionData || sessionData.expires < Date.now()) {
      console.log('❌ Token inválido ou expirado');
      return jsonResponse({ success: false, error: 'Token inválido ou expirado' }, 401);
    }

    console.log('✅ Token válido para:', sessionData.user.email, 'Role:', sessionData.user.role);

    return jsonResponse({
      success: true,
      user: sessionData.user
    });

  } catch (err) {
    console.error('❌ fielVerificarRoute:', err);
    return jsonResponse({ success: false, error: 'Erro interno: ' + err.message }, 500);
  }
}

// ============================================
// 4. VERIFICAR PIN (COM SETUP 2FA REAL)
// ============================================
export async function fielVerifyPinRoute(request, env) {
  try {
    const body = await request.json();
    const { userId, pin, celular } = body;

    console.log('🔐 Verificando PIN - userId:', userId);

    if (!userId || !pin) {
      return jsonResponse({ success: false, error: 'Dados incompletos' });
    }

    const user = await env.DB.prepare(
      `SELECT id, nome, email, login_pin, login_pin_expires, twofa_enabled, twofa_secret, role
       FROM users WHERE id = ?`
    ).bind(userId).first();

    if (!user) {
      return jsonResponse({ success: false, error: 'Usuário não encontrado' });
    }

    if (!user.login_pin) {
      return jsonResponse({ success: false, error: 'Nenhum PIN ativo. Solicite um novo.' });
    }
    if (Date.now() > user.login_pin_expires) {
      return jsonResponse({ success: false, error: 'PIN expirado. Solicite um novo.' });
    }
    if (user.login_pin !== pin) {
      return jsonResponse({ success: false, error: 'PIN inválido' });
    }

    await env.DB.prepare(
      `UPDATE users SET login_pin = NULL, login_pin_expires = NULL WHERE id = ?`
    ).bind(user.id).run();

    if (celular && validarCelular(celular)) {
      await env.DB.prepare(
        `UPDATE users SET celular = ? WHERE id = ? AND (celular IS NULL OR celular = '')`
      ).bind(celular.replace(/\D/g, ''), user.id).run();
    }

    console.log('✅ PIN verificado para:', user.email);

    // Se já tem 2FA configurado, vai direto pra verificação
    if (user.twofa_secret) {
      return jsonResponse({ 
        success: true, 
        nextStep: '2fa-verify',
        userId: user.id,
        role: user.role,
        isAdmin: user.role === 'admin'
      });
    }

    // 🔥 PRIMEIRO ACESSO - SETUP 2FA REAL
    
    // Gera secret BASE32 válido
    const secretKey = generateBase32Secret();

    // Monta URI compatível com Google Authenticator
    const issuer = 'SantuarioFatima';
    const label = `${issuer}:${user.email}`;
    const otpauth = `otpauth://totp/${encodeURIComponent(label)}?secret=${secretKey}&issuer=${issuer}`;

    // Gera QR Code URL
    const qrCodeUrl = 'https://chart.googleapis.com/chart?chs=200x200&cht=qr&chl=' + encodeURIComponent(otpauth);

    // Gera backup codes com hash
    const backupCodes = generateBackupCodes();
    const hashedBackupCodes = await Promise.all(backupCodes.map(c => sha256(c)));
    
    // Salva no banco
    await env.DB.prepare(
      `UPDATE users SET twofa_secret = ?, backup_codes = ? WHERE id = ?`
    ).bind(secretKey, JSON.stringify(hashedBackupCodes), user.id).run();

    // Retorna dados para o front configurar o 2FA
    return jsonResponse({
      success: true,
      nextStep: '2fa-setup',
      userId: user.id,
      nome: user.nome,
      email: user.email,
      role: user.role,
      isAdmin: user.role === 'admin',
      qrCodeUrl,
      secretKey,
      backupCodes
    });

  } catch (err) {
    console.error('❌ fielVerifyPinRoute:', err);
    return jsonResponse({ success: false, error: 'Erro interno: ' + err.message }, 500);
  }
}

