import { sha256 } from '../security/hash.js';

// 🔐 Busca sessão no KV
async function getSession(request, env) {
  try {
    const authHeader = request.headers.get('Authorization');
    const token = authHeader?.replace('Bearer ', '');

    if (!token) return null;

    const hash = await sha256(token);

    const session = await env.KV_SESSIONS.get(`sess:${hash}`, 'json');

    if (!session) return null;

    if (Date.now() > session.expires) return null;

    return session;

  } catch (err) {
    console.error('Erro getSession:', err);
    return null;
  }
}

// ============================================
// 🔐 REQUIRE AUTH
// ============================================
async function requireAuth(request, env) {
  const session = await getSession(request, env);

  if (!session) {
    return new Response('Não autorizado', { status: 401 });
  }

  return session;
}

// ============================================
// 🔐 REQUIRE ROLE
// ============================================
function requireRole(role) {
  return async (request, env) => {
    const session = await getSession(request, env);

    if (!session) {
      return new Response('Não autorizado', { status: 401 });
    }

    if (session.user.role !== role) {
      return new Response('Acesso negado', { status: 403 });
    }

    return session;
  };
}

// ============================================
// 🔐 REQUIRE FIEL
// ============================================
async function requireFiel(request, env) {
  const session = await getSession(request, env);

  if (!session) {
    return new Response('Não autorizado', { status: 401 });
  }

  if (session.user.role !== 'fiel') {
    return new Response('Acesso negado', { status: 403 });
  }

  return session;
}

// 🔥 EXPORT EXPLÍCITO (IMPORTANTE)
export { requireAuth, requireRole, requireFiel };